// Solution for: Parcel Shipping Desk
import java.util.*; public class W92_q2 {public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();double kg=s.nextDouble(),value=s.nextDouble(),charge,ins=0;if(t.equals("STANDARD"))charge=40+10*kg;else if(t.equals("EXPRESS")){charge=80+15*kg;ins=.02*value;}else{charge=40+10*kg+50;ins=.02*value;}System.out.printf("%s: Charge=%.2f Insurance=%.2f Total=%.2f%n",t,charge,ins,charge+ins);total+=charge+ins;}System.out.printf("Grand Total: %.2f%n",total);}}
